      if (w.quoted) line("Context", "includes a quoted post");
      if (w.examples) line("Learned from you", `${w.examples} similar votes used` + (w.creatorVotes ? `; this creator: ${w.creatorVotes.marked_slop} slop / ${w.creatorVotes.marked_not_slop} not` : ""));
